// Lee la respuesta de Claude y la convierte en columnas
const r = $input.first().json;
if (r.stop_reason === 'refusal') {
  throw new Error('Claude no procesó este documento (refusal).');
}
const bloque = (r.content || []).find(b => b.type === 'text');
if (!bloque) throw new Error('Respuesta sin texto: ' + JSON.stringify(r).slice(0, 300));
const datos = JSON.parse(bloque.text);
const archivo = $('Formulario de factura').first().binary.factura?.fileName || 'factura.pdf';
return [{ json: { archivo, ...datos } }];

